import { createHash as createHash2 } from "node:crypto";
function sha256HexBuffer(data) {
  return createHash2("sha256").update(data).digest("hex");
}

// services/profile/src/http/routes/upload-resume.ts
var UNIQUE_VIOLATION = "23505";
var sourceSchema = external_exports.enum(["upload", "connector", "import"]).default("upload");
function uploadResumeRoute(app, deps) {
  app.post(
    "/v1/resumes",
    { preHandler: requireAuth(deps.tokenVerifier), config: { rateLimit: { max: 20, timeWindow: "1 minute" } } },
    async (request, reply) => {
      const actor = getActor(request);
      const data = await request.file();
      if (!data || data.fieldname !== "file") {
        throw new AppError("VALIDATION_ERROR", 'Expected a multipart file field named "file"');
      }
      const sourceField = data.fields.source;
      const rawSource = sourceField && !Array.isArray(sourceField) && sourceField.type === "field" ? sourceField.value : void 0;
      sourceSchema.parse(rawSource);
      const buffer2 = await data.toBuffer();
      const contentHash = sha256HexBuffer(buffer2);
      const existing = await findByUserAndHash(deps.db, actor.user_id, contentHash);
      if (existing) {
        const response2 = { resume_id: existing.resumeId, status: existing.status };
        reply.status(200).send(response2);
        return;
      }
      const storageKey = `resumes/${actor.user_id}/${contentHash}`;
      await deps.storage.put(storageKey, buffer2, { contentType: data.mimetype });
      let resumeId;
      try {
        const resume = await insertPending(deps.db, {
          userId: actor.user_id,
          storageUrl: storageKey,
          originalFilename: data.filename,
          contentType: data.mimetype,
          byteSize: buffer2.length,
          contentHash
        });
        resumeId = resume.resumeId;
      } catch (cause) {
        if (pgErrorCode(cause) === UNIQUE_VIOLATION) {
          const raced = await findByUserAndHash(deps.db, actor.user_id, contentHash);
          if (raced) {
            const response2 = { resume_id: raced.resumeId, status: raced.status };
            reply.status(200).send(response2);
            return;
          }
        }
        throw cause;
      }
      let parsed = null;
      try {
        const text2 = await extractText(buffer2, data.mimetype);
        const profile = parseResumeText(text2);
        const report = scoreResume(profile, text2);
        await markParsed(deps.db, resumeId, {
          parsedText: text2,
          parsedProfile: profile,
          atsScore: report.score,
          atsReport: report
        });
        parsed = { profile, report };
      } catch (cause) {
        const reason = cause instanceof Error ? cause.message : String(cause);
        await markFailed(deps.db, resumeId, reason);
        const response2 = { resume_id: resumeId, status: "failed" };
        reply.status(201).send(response2);
        return;
      }
      try {
        await deps.broker.publish(
          createEvent(
            "resume.parsed",
            {
              resume_id: resumeId,
              user_id: actor.user_id,
              ats_score: parsed.report.score,
              skill_count: parsed.profile.skills.length,
              total_months_experience: parsed.profile.total_months_experience
            },
            newTraceContext({ organization_id: actor.organization_id, user_id: actor.user_id })
          )
        );
      } catch (cause) {
        request.log.error({ err: cause, resumeId }, "failed to publish resume.parsed event");
      }
      const response = { resume_id: resumeId, status: "parsed" };
      reply.status(201).send(response);
    }
  );
}

// services/profile/src/app.ts
var STATUS_TO_CODE = {
  400: "VALIDATION_ERROR",
  413: "PAYLOAD_TOO_LARGE",
  415: "UNSUPPORTED_MEDIA_TYPE",
  429: "RATE_LIMITED"
};
function buildApp(deps) {
  const app = (0, import_fastify.default)({
    // See services/auth/src/app.ts for why this cast is needed: pino's Logger
    // type and Fastify's FastifyBaseLogger disagree on a structural detail
    // that doesn't matter at runtime.
    loggerInstance: deps.logger,
    bodyLimit: deps.env.BODY_LIMIT_BYTES,
    trustProxy: true,
    genReqId: () => newUuid()
  });
  void app.register(import_cors.default, { origin: parseCorsOrigins(deps.env.CORS_ORIGINS) });
  void app.register(import_rate_limit.default, {
    max: deps.env.RATE_LIMIT_MAX,
    timeWindow: deps.env.RATE_LIMIT_WINDOW
  });
  void app.register(import_multipart.default, {
    limits: { fileSize: deps.env.BODY_LIMIT_BYTES, files: 1 }
  });
  const metrics2 = createMetricsRegistry("profile-service");
  registerHttpMetrics(app, metrics2);
  app.setErrorHandler((error51, request, reply) => {
    if (error51 instanceof ZodError) {
      reply.status(400).send({
        error: {
          code: "VALIDATION_ERROR",
          message: "Request failed validation",
          request_id: request.id,
          details: error51.issues.map((issue2) => ({ path: issue2.path.join("."), message: issue2.message }))
        }
      });
      return;
    }
    if (isAppError(error51)) {
      reply.status(error51.statusCode).send(error51.toResponse(request.id));
      return;
    }
    const fastifyStatus = error51.statusCode;
    if (fastifyStatus !== void 0 && fastifyStatus >= 400 && fastifyStatus < 500) {
      reply.status(fastifyStatus).send({
        error: {
          code: STATUS_TO_CODE[fastifyStatus] ?? "VALIDATION_ERROR",
          message: error51.message,
          request_id: request.id
        }
      });
      return;
    }
    request.log.error({ err: error51 }, "unhandled error");
    const appError = toAppError(error51);
    reply.status(appError.statusCode).send(appError.toResponse(request.id));
  });
  app.setNotFoundHandler((request, reply) => {
    reply.status(404).send({
      error: { code: "NOT_FOUND", message: "Route not found", request_id: request.id }
    });
  });
  healthRoute(app, deps);
  metricsRoute(app, metrics2);
  uploadResumeRoute(app, deps);
  getResumeRoute(app, deps);
  listResumesRoute(app, deps);
  return app;
}

