// services/profile/src/index.ts
async function main() {
  const env2 = loadProfileServiceEnv();
  const logger = createLogger({ service: "profile-service", level: env2.LOG_LEVEL, pretty: env2.LOG_PRETTY });
  const { db, sql: sql2, close } = createDatabase({ url: env2.DATABASE_URL, maxConnections: env2.DATABASE_POOL_MAX });
  const broker = createBroker({
    driver: env2.MESSAGING_DRIVER,
    url: env2.RABBITMQ_URL,
    exchange: env2.MESSAGING_EXCHANGE,
    maxRetries: env2.MESSAGING_MAX_RETRIES,
    logger
  });
  const storage = createStorage({ driver: env2.STORAGE_DRIVER, localRoot: env2.STORAGE_LOCAL_ROOT });
  const tokenVerifier = createTokenVerifierConfig(env2);
  const app = buildApp({ db, sql: sql2, env: env2, logger, broker, storage, tokenVerifier });
  const shutdown = async (signal) => {
    logger.info({ signal }, "shutting down");
    await app.close();
    await broker.close();
    await close();
    process.exit(0);
  };
  process.on("SIGTERM", () => void shutdown("SIGTERM"));
  process.on("SIGINT", () => void shutdown("SIGINT"));
  await app.listen({ host: env2.HOST, port: env2.PORT });
}
main().catch((error51) => {
  console.error(error51);
  process.exit(1);
});
